"use client";

import type { Sample } from "@/domains/sample/entities";
import { useMemo, useState } from "react";
import { BulkActionItems, DataTable, RecordSelectionTable, TableCellAction, selectBulkActions, type DataTableColumn } from "@/lib/tableSuite";
import { useDomainAdminBulkActions } from "@/domains/core/admin/hooks/useDomainAdminBulkActions";
import type { SampleAdminBulkActionItem } from "@/domains/sample/types/adminBulkAction";
import { useAdminBulkActionCan } from "@/domains/core/user/hooks/useAdminBulkActionCan";
import { EditButton, DuplicateButton, DeleteButton } from "@/lib/crud";
import presenters from "@/domains/sample/presenters";
import SampleDetailModal from "../common/SampleDetailModal";
import { buildDomainColumns } from "@/lib/crud";
import { formatDateJa } from "@/utils/date";
import { truncateJapanese } from "@/utils/string";
import { adminConfig } from "@/domains/admin/config";
import { domainDisplay as sampleDisplay } from "@/domains/sample/entities/display";

export type AdminSampleListTableProps = {
  /**
   * Records to display. Optional so the component can render before data loads
   * without throwing errors.
   */
  samples?: Sample[];
};

const { dataTable } = adminConfig;
const adminDataTableFallback = dataTable.emptyFieldFallback ?? "(未設定)";

const columns: DataTableColumn<Sample>[] = buildDomainColumns<Sample>({
  config: sampleDisplay,
  formatDate: formatDateJa,
  truncate: truncateJapanese,
  presenters,
  actionColumn: {
    header: "操作",
    render: (d: Sample) => (
      <TableCellAction>
        <EditButton domain={sampleDisplay} id={d.id} />
        <DuplicateButton domain={sampleDisplay} id={d.id} currentName={d.name} />
        <DeleteButton domain={sampleDisplay} id={d.id} />
      </TableCellAction>
    ),
  },
});

export default function AdminSampleListTable({ samples }: AdminSampleListTableProps) {
  const [selectedId, setSelectedId] = useState<string | null>(null);
  // 一括操作: 点 adminBulkActions の項目のうちこのドメインの物(<ドメイン>/plugs/adminBulkActions/<名前>.tsx。D149、門番で閉じた項目は外れる)。項目が無ければ素の表
  const can = useAdminBulkActionCan();
  const domainBulkActions = useDomainAdminBulkActions<SampleAdminBulkActionItem>("sample");
  const bulkActionItems = useMemo(() => selectBulkActions(domainBulkActions, { can }), [domainBulkActions, can]);

  return (
    <>
      {bulkActionItems.length === 0 ? (
        <DataTable
          items={samples ?? []}
          columns={columns}
          getKey={(d) => d.id}
          rowClassName="cursor-pointer"
          onRowClick={(d) => setSelectedId(String(d.id))}
          emptyValueFallback={adminDataTableFallback}
        />
      ) : (
        <RecordSelectionTable
          items={samples ?? []}
          columns={columns}
          getKey={(d) => d.id}
          rowClassName="cursor-pointer"
          // 行のクリックは詳細を開くので、選択はチェックボックスだけ
          selectionBehavior="checkbox"
          onRowClick={(d) => setSelectedId(String(d.id))}
          emptyValueFallback={adminDataTableFallback}
          bulkActions={(selection) => <BulkActionItems items={bulkActionItems} selection={selection} />}
        />
      )}
      <SampleDetailModal
        sampleId={selectedId}
        open={selectedId !== null}
        onOpenChange={(open) => {
          if (!open) {
            setSelectedId(null);
          }
        }}
      />
    </>
  );
}
